# construct accurately from test cells
G=[[1]*30 for _ in range(30)]
objects={4:[(3,7),(4,6),(4,8),(5,5),(5,6),(5,8)],2:[(3,13),(4,12),(5,11),(21,21),(21,22)],8:[(1,23),(2,22),(3,22)],5:[(9,25),(10,24),(10,25)],6:[(11,5),(12,5),(12,7)],3:[(11,15),(12,16),(13,16)],7:[(19,11),(20,12)],9:[(22,5),(23,3)]}
for col,pts in objects.items():
 for r,c in pts:G[r][c]=col
base={(r-3,c-5) for r,c in objects[4]}
# all 8 symmetries; optimize overlap then translation closest seed bbox
import itertools
transforms=[]
for k in range(4):
 for refl in [False,True]:
  s=set()
  for r,c in base:
   x,y=r,c
   if refl:y=-y
   for _ in range(k): x,y=y,-x
   s.add((x,y))
  mi=min(x for x,y in s); mj=min(y for x,y in s)
  transforms.append({(x-mi,y-mj) for x,y in s})
for col,pts in objects.items():
 if col==4:continue
 candidates=[]
 for shape in transforms:
  for dr in range(30):
   for dc in range(30):
    hit=sum((r-dr,c-dc) in shape for r,c in pts)
    if hit==len(pts):candidates.append((shape,dr,dc))
 if not candidates:
  # maximum overlap fallback
  for shape in transforms:
   for dr in range(30):
    for dc in range(30): candidates.append((shape,dr,dc))
 best=max(candidates,key=lambda x:(sum((r-x[1],c-x[2]) in x[0] for r,c in pts),-abs(x[1]-min(r for r,c in pts)),-abs(x[2]-min(c for r,c in pts))))
 sh,dr,dc=best
 for a,b in sh:
  if dr+a<30 and dc+b<30:G[dr+a][dc+b]=col
print(G)

G2=[row[:] for row in G] # replace based original construct G input from objects
G2=[[1]*30 for _ in range(30)]
for col,pts in objects.items():
 for r,c in pts:G2[r][c]=col
for color in objects:
 if color==4:continue
 ptsall=set(objects[color]); comps=[]
 while ptsall:
  st=[ptsall.pop()]; comp=set(st)
  while st:
   r,c=st.pop()
   for q in list(ptsall):
    if abs(q[0]-r)+abs(q[1]-c)==1:ptsall.remove(q);comp.add(q);st.append(q)
  comps.append(comp)
 for pts in comps:
  cand=[]
  for shape in transforms:
   for dr in range(30):
    for dc in range(30):
     hit=sum((r-dr,c-dc) in shape for r,c in pts)
     cand.append((hit,shape,dr,dc))
  hit,sh,dr,dc=max(cand,key=lambda x:(x[0],-abs(x[2]-min(r for r,c in pts)),-abs(x[3]-min(c for r,c in pts))))
  for a,b in sh:
   if dr+a<30 and dc+b<30:G2[dr+a][dc+b]=color
print(json.dumps({'action':'submit','grid':G2}))

for col,pts in [(8,objects[8]),(6,objects[6]),(3,objects[3]),(5,objects[5]),(7,objects[7]),(9,objects[9])]:
 print('\n',col,pts)
 for sh in transforms:
  for dr in range(30):
   for dc in range(30):
    if all((r-dr,c-dc) in sh for r,c in pts): print(dr,dc,sh);break
   else: continue
   break

# exact-only choose placement nearest seed min; inspect result sparse additions
GG=[[1]*30 for _ in range(30)]
for col,pts in objects.items():
 for r,c in pts: GG[r][c]=col
for col in [8,6,3,5,7,9,2]:
 points=objects[col]
 # split 2 disconnected by hand
 if col==2: components=[[(3,13),(4,12),(5,11)],[(21,21),(21,22)]]
 else: components=[points]
 for pp in components:
  cand=[]
  for sh in transforms:
   for dr in range(30):
    for dc in range(30):
     if all((r-dr,c-dc) in sh for r,c in pp):cand.append((sh,dr,dc))
  sh,dr,dc=min(cand,key=lambda x:(abs(x[1]-min(r for r,c in pp))+abs(x[2]-min(c for r,c in pp)),x[1],x[2]))
  for a,b in sh:
   if dr+a<30 and dc+b<30:GG[dr+a][dc+b]=col
print(json.dumps({'action':'submit','grid':GG}))

# inspect exact candidate translations for 2 shapes and select least top-left aligned option
for pts in [[(3,13),(4,12),(5,11)],[(21,21),(21,22)]]:
 opts=[]
 for i,sh in enumerate(transforms):
  for dr in range(30):
   for dc in range(30):
    if all((r-dr,c-dc) in sh for r,c in pts):opts.append((dr,dc,i))
 print(pts,opts[:30])
